-- PT122-S4-Q25. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT122-S4-Q25$batch03$ AND q.stimulus=$batch03$A study conducted over a 6-month period analyzed daily attendance and average length of visit at the local art museum. The results showed that when the museum was not featuring a special exhibition, attendance tended to be lower but patrons spent an average of 45 minutes longer in the museum than when it was featuring a special exhibition.$batch03$ AND q.prompt=$batch03$Each of the following, if true, could help to explain the differing average lengths of visits to the museum EXCEPT:$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT122-S4-Q25'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT122-S4-Q25$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S4-Q25'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT122-S4-Q25$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Attendance is higher during special exhibitions.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Visitors stay 45 minutes longer when there is no special exhibition?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Something about exhibition visits makes them shorter: narrower interest, rushing for prestige, timed tickets, guided tours. Each working answer gives exhibition visitors a reason to leave sooner.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices give a reason exhibition visits are shorter. The answer will not affect visit length.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT122-S4-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Exhibition visitors have narrow interests and see fewer exhibits, so their visits are shorter.$batch03$), ($batch03$B$batch03$, $batch03$A plan to extend hours was considered but *not* enacted. Nothing changed, so it cannot explain any difference in visit length.$batch03$), ($batch03$C$batch03$, $batch03$People there for prestige only need to show up, not linger.$batch03$), ($batch03$D$batch03$, $batch03$One-hour tickets limit how long exhibition visitors stay.$batch03$), ($batch03$E$batch03$, $batch03$Tour groups follow a schedule and cannot browse, so their visits are shorter.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT122-S4-Q25$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
